'use strict'

//note(dgmid): built-in "Default" AI profile — always present, never deletable.
//It defines the baseline policy for BOTH folder organization and tagging:
//
//  - Folder names: a coarse, hierarchical taxonomy — ONE home per bookmark, named
//    after the domain it belongs to (subject, organization or area of interest).
//  - Tags: flat, combinable facets — SEVERAL per bookmark, describing type,
//    language, status or cross-cutting topic.
//
//User-learned profiles are additional. The Default profile is what Auto-Organize
//and Auto-Tag fall back to when no learned profile is chosen, and "Reset Learning"
//re-seeds the store with it.

const DEFAULT_PROFILE = {
	id: 'default',
	builtin: true,
	name: 'Default',
	description: 'Folder names form a coarse hierarchical taxonomy: assign each bookmark ONE home folder named after the domain it belongs to (subject, organization or area, 2 to 4 words, descriptive). Tags are flat combinable facets: assign each bookmark SEVERAL short lowercase terms describing type, language, status or cross-cutting topic.',
	folderNames: ['University', 'Documentation', 'Projects', 'Personal'],
	tagExamples: [
		{ tag: 'tutorial', count: 0, examples: [] },
		{ tag: 'reference', count: 0, examples: [] },
		{ tag: 'tool', count: 0, examples: [] },
		{ tag: 'todo', count: 0, examples: [] },
		{ tag: 'spanish', count: 0, examples: [] },
		{ tag: 'english', count: 0, examples: [] }
	]
}



//note(dgmid): clone so callers can't mutate the shared constant

module.exports.getDefaultProfile = function() {
	
	return JSON.parse( JSON.stringify( DEFAULT_PROFILE ) )
}



//note(dgmid): is this the built-in default profile (by flag or id)?

module.exports.isBuiltin = function( p ) {
	
	return !!( p && ( p.builtin === true || String( p.id ) === 'default' ) )
}



//note(dgmid): make sure the built-in default profile is ALWAYS the first entry of
//store.aiProfiles. Called by every consumer (auto-tag, auto-organize, ai-config)
//so the invariant holds even if a previous version stored an empty list.

module.exports.ensureDefaultProfile = function( store ) {
	
	let profiles = store.get( 'aiProfiles' )
	
	if( !Array.isArray( profiles ) ) profiles = []
	
	if( !profiles.some( p => module.exports.isBuiltin( p ) ) ) {
		
		profiles.unshift( module.exports.getDefaultProfile() )
		store.set( 'aiProfiles', profiles )
	}
	
	return store.get( 'aiProfiles' ) || []
}

